def test_case(name, content):
    open('/tmp/test/tmp.conf','w').write(content)
    os.system('PATH=/tmp/fakebin:$PATH ./executable solarized --config /tmp/test/tmp.conf > /tmp/test/stdout.txt 2>/tmp/test/stderr.txt')
    print(f"=== {name} ===")
    print("INPUT:")
    for l in content.splitlines():
        print(f"  indent={count_indent(l):2d} |{l}|")
    print("OUTPUT:")
    out=open('/tmp/test/stdout.txt').read().splitlines()
    for l in out:
        # show indent
        print(f"  indent={count_indent(l):2d} |{l}|")
    print()

